WHERE {
  VALUES ?graph {
    <urn:graphragprov:unit:u_0bfaf78bd3e84520>
    <urn:graphragprov:unit:u_67dedade97e92d3f>
  }
  GRAPH ?graph {
    ?subject ?predicate ?object .
